local ECSComponent = import("Frame.ECS.ECSComponent")

---@type OverseaStoreHomeDojo
local OverseaStoreHomeDojo = import("Game.OverseaStore.OverseaStoreHomeDojo")

---@class OverseaStoreComponent
local OverseaStoreComponent = Class("OverseaStoreComponent", ECSComponent)

---@type OverseaStoreConstants
local OverseaStoreConstants = import('Game.OverseaStore.OverseaStoreConstants')

function OverseaStoreComponent:__init()
    self.name = "OverseaStoreComponent"
    ---@type OverseaStoreHomeDojo
    self._storeHomeDojo = OverseaStoreHomeDojo.New()
end

function OverseaStoreComponent:__delete()
    self._storeHomeDojo = nil

end

---初始化
---@param jsonData table 服务器返回的商城数据
function OverseaStoreComponent:Initial(jsonData)
    self:GetStoreHomeDojo():Fill(jsonData)
   self:InitialDailyOfferData(self:GetStoreHomeDojo().dailyOffer)
end

function OverseaStoreComponent:RequestKrDiamondData(callback)
    GameUtils.Request(Interfaces.OverseaMallKrDiamond, nil, function(request,response)
        self:SetPrimaryCurrencyData(checkTable(response.data.krDiamond))
        if callback then
            callback()
        end
    end)
end

function OverseaStoreComponent:InitialDailyOfferData(data)
    data = data or {}
    local DailyOfferDojo = import('Game.Dojo.DailyOfferDojo')
    -- 先重置数据
    local dojos = {}
    for i, v in pairs(data) do
        ---@type DailyOfferDojo
        local dojo = DailyOfferDojo.New()
        dojo = dojo:Fill(v)
        dojos[#dojos+1] = dojo
    end
    self._storeHomeDojo.dailyOffer = dojos
end

---@param dailyOfferId number 每日特惠Id
---@return DailyOfferDojo
function OverseaStoreComponent:GetDailyOfferDataByDailyOfferId(dailyOfferId)
    local dailyOfferId = checkInt(dailyOfferId)
    for i, dojo in pairs(self._storeHomeDojo.dailyOffer) do
        if checkInt(dojo.dailyOfferId) == dailyOfferId then
            return dojo
        end
    end
end
---@return DailyOfferDojo
function OverseaStoreComponent:GetDailyOfferWeeklyDojo()
    local DAILY_OFFER_TYE = {
        FREE = 0,
        DAILY = 1 ,
        WEEKLY = 2
    }
    for i, dojo in pairs(self._storeHomeDojo.dailyOffer) do
        ---@type DailyOfferVo
        local dailyOfferVo = CfUtils.GetCfVo(AutoIds.IdSetting4040,"DailyOfferVo",dojo.dailyOfferId)
        if checkInt(dailyOfferVo.giftType) == DAILY_OFFER_TYE.WEEKLY then
            return dojo
        end
    end
    return nil
end

---减少库存
---@param storeType OverseaStoreConstants.StoreType
---@param productId   integer 商品id
---@param buyNum      integer 购买数量
function OverseaStoreComponent:ReduceStock(storeType, productId, buyNum)
    local data = self:GetStoreDataByType(storeType)
    for i, v in ipairs(checkTable(data.products)) do
        if v.stock ~= -1 then
            if checkInt(v.productId) == productId then
                v.currentStock = v.currentStock - buyNum
                break
            end
        end
    end
end

---减少倒计时
---@param deltaTime number 经过的时间
function OverseaStoreComponent:DecreaseTime(deltaTime)
    local homeDojo = self:GetStoreHomeDojo()
    for _, v in pairs(homeDojo) do
        if type(v) == "table" then
            if v.nextRefreshLeftSeconds then
                v.nextRefreshLeftSeconds = tonumber(v.nextRefreshLeftSeconds) - deltaTime
            elseif v.products then
                for _, product in ipairs(checkTable(v.products)) do
                    if product.endTime then
                        product.endTime = tonumber(product.endTime) - deltaTime
                    end
                    if product.nextRefreshLeftSeconds then
                        product.nextRefreshLeftSeconds = tonumber(product.nextRefreshLeftSeconds) - deltaTime
                    end
                end
            end
        end
    end
end

---获取OverseaStoreHomeDojo
---@return OverseaStoreHomeDojo
function OverseaStoreComponent:GetStoreHomeDojo()
    return self._storeHomeDojo
end

---通过商城类型获取商城数据（需在config中配置dataKey）
---@param storeType OverseaStoreConstants.StoreType
function OverseaStoreComponent:GetStoreDataByType(storeType)
    local config = OverseaStoreConstants.StorePanelConfigs[storeType]
    if not config or not config.dataKey then return end

    local homeDojo = self:GetStoreHomeDojo()
    return checkTable(homeDojo[config.dataKey])
end

